import{_ as s,r as t,o as l,c as o,e as a,a as r,s as g}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Installing the Plugin - October CMS User Guide","titleTemplate":false,"description":"Install the Responsiv Campaign plugin and create your first subscriber list.","frontmatter":{"subtitle":"Install the Responsiv Campaign plugin and create your first subscriber list."},"headers":[{"level":2,"title":"Installing the Plugin","slug":"installing-the-plugin","link":"#installing-the-plugin","children":[]},{"level":2,"title":"Creating a Subscriber List","slug":"creating-a-subscriber-list","link":"#creating-a-subscriber-list","children":[]},{"level":2,"title":"Generating the Default Template","slug":"generating-the-default-template","link":"#generating-the-default-template","children":[]},{"level":2,"title":"How Campaign Templates Work","slug":"how-campaign-templates-work","link":"#how-campaign-templates-work","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/mailing-list/installing-the-plugin.md","filePath":"user-guide/mailing-list/installing-the-plugin.md"}'),p={name:"user-guide/mailing-list/installing-the-plugin.md"};function d(c,e,u,h,m,f){const i=t("pre-heading"),n=t("post-heading");return l(),o("div",null,[a(i),e[0]||(e[0]=r("h1",null,"Installing the Plugin",-1)),a(n),e[1]||(e[1]=g(`<p>The Responsiv Campaign plugin provides everything you need for email marketing: subscriber management, campaign composition with a visual editor, template syntax fields, scheduled and staggered sending, open tracking, and automatic unsubscribe handling.</p><h2 id="installing-the-plugin"><a href="#installing-the-plugin" class="header-anchor">#</a> Installing the Plugin</h2><p>Navigate to <strong>Settings &gt; Updates &amp; Plugins &gt; Install Packages</strong> and search for &quot;Responsiv.Campaign&quot;. Click <strong>Install</strong> to add it to your project.</p><p>Alternatively, install via the command line:</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan plugin:install Responsiv.Campaign
</code></pre></div><p>After installation, you will see a new <strong>Mailing List</strong> section in the backend navigation with links to <strong>Campaigns</strong>, <strong>Lists</strong>, <strong>Subscribers</strong>, and <strong>Settings</strong>.</p><h2 id="creating-a-subscriber-list"><a href="#creating-a-subscriber-list" class="header-anchor">#</a> Creating a Subscriber List</h2><p>Navigate to <strong>Mailing List &gt; Lists</strong> and click <strong>New List</strong>. Create a list with the following details:</p><div class="table"><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>Newsletter</td></tr><tr><td>Code</td><td><code>newsletter</code></td></tr></tbody></table></div><p>Subscriber lists are opt-in groups that visitors join via signup forms on your site. You can create multiple lists for different purposes (e.g., a product updates list and a blog digest list). Each list tracks its own subscribers independently.</p><h2 id="generating-the-default-template"><a href="#generating-the-default-template" class="header-anchor">#</a> Generating the Default Template</h2><p>Navigate to <strong>Mailing List &gt; Campaigns</strong> and click <strong>New Campaign</strong>. Since no campaign template pages exist yet, the plugin offers to generate one for you. Click <strong>Create a Default Template</strong> to create a default CMS page at <code>campaign/default-template.htm</code> with the <code>campaignTemplate</code> component already attached.</p><p>This page serves as the HTML scaffold for all your campaign emails. You will customize it later, but the default template gives you a working starting point with a header, banner image, content sections, and footer.</p><p>After the template is generated, close the campaign creation dialog. You will create your first campaign after setting up the signup form.</p><h2 id="how-campaign-templates-work"><a href="#how-campaign-templates-work" class="header-anchor">#</a> How Campaign Templates Work</h2><p>Campaign templates are CMS pages with the <code>campaignTemplate</code> component. Unlike regular pages, they do not use a site layout. Instead, they contain a complete HTML email document with inline styles and table-based formatting (required for email client compatibility).</p><p>Templates use a special syntax for editable fields:</p><ul><li><code>{text name=&quot;greeting&quot; label=&quot;Greeting&quot;}Default value{/text}</code>: a single-line text input</li><li><code>{textarea name=&quot;intro&quot; label=&quot;Introduction&quot;}{/textarea}</code>: a multi-line text input</li><li><code>{richeditor name=&quot;body&quot; label=&quot;Content&quot;}{/richeditor}</code>: a WYSIWYG content editor</li><li><code>{fileupload name=&quot;banner&quot; label=&quot;Banner image&quot;}{/fileupload}</code>: a file upload field</li><li><code>{repeater name=&quot;sections&quot; prompt=&quot;Add section&quot;}...{/repeater}</code>: repeatable groups of fields</li></ul><p>When you create a campaign and select a template, these syntax fields appear as an editable form in the backend. The content you enter is rendered into the template HTML and sent to subscribers.</p><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Continue to <a href="./signup-form.html">Signup Form</a> to create a subscription form that visitors can use to join your mailing list.</p>`,21))])}const y=s(p,[["render",d]]);export{v as __pageData,y as default};
